package com.digitalbase.ticketing.controller;import com.digitalbase.ticketing.dto.CompanySlaOverviewResponse;import com.digitalbase.ticketing.dto.SlaHourSummaryResponse;import com.digitalbase.ticketing.enums.SlaStatus;import com.digitalbase.ticketing.service.SlaManagementService; // 👈 Interface ကို Import လုပ်ပါimport lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/admin/sla")@RequiredArgsConstructorpublic class SlaManagementController {    // 🎯 အရေးကြီးပါသည် - SlaManagementServiceImpl အစား SlaManagementService (Interface) ကိုသာ Inject လုပ်ပါ    private final SlaManagementService slaManagementService;    @GetMapping("/summary")    public ResponseEntity<SlaHourSummaryResponse> getSummary() {        return ResponseEntity.ok(slaManagementService.getSlaSummary());    }    @GetMapping("/overview")    public ResponseEntity<Page<CompanySlaOverviewResponse>> getOverview(            @RequestParam(required = false) String search,            @RequestParam(required = false) SlaStatus status,            @RequestParam(defaultValue = "0") int page,            @RequestParam(defaultValue = "10") int size) {        return ResponseEntity.ok(slaManagementService.getCompanySlaOverview(search, status, page, size));    }}